insert into trip_alternatives (key, label, data)
values ('mauritius', 'Mauritius', $q${"label":"Mauritius","emoji":"🌴","title":"Honeymoon, but make it island-spicy. 🌶️","tagline":"Mauritius: coloured earth, Port Louis markets, lagoon beaches and zero pressure to “do it all”.","heroImage":"hero","cap":400000,"defaultOption":"boutique","images":{"hero":{"file":"mauritius/hero.jpg","credit":"Photo: \"dronepicr\", CC BY 2.0, via Wikimedia Commons","source":"https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_southwest_of_Mauritius_(53698214005).jpg"},"lemorne":{"file":"mauritius/lemorne.jpg","credit":"Photo: \"dronepicr\", CC BY 2.0, via Wikimedia Commons","source":"https://commons.wikimedia.org/wiki/File:Le_Morne_Beach_with_Le_Morne_Brabant_Mountain_in_the_background,_Mauritius_(53698223315).jpg"},"chamarel":{"file":"mauritius/chamarel.jpg","credit":"Photo: CEphoto, Uwe Aranas, CC BY-SA 3.0, via Wikimedia Commons","source":"https://commons.wikimedia.org/wiki/File:Mauritius_Seven-Coloured-Earths-01.jpg"},"market":{"file":"mauritius/market.jpg","credit":"Photo: Sushil Dawka, CC BY-SA 4.0, via Wikimedia Commons","source":"https://commons.wikimedia.org/wiki/File:Herbal_tisanes_for_several_ailments_on_sale_at_the_Central_Market,_Port_Louis,_Mauritius.jpg"},"waterfront":{"file":"mauritius/waterfront.jpg","credit":"Photo: Benoît Prieur, CC0, via Wikimedia Commons","source":"https://commons.wikimedia.org/wiki/File:Caudan_Waterfront_(Port_Louis),_vue_d%27un_canal.jpg"},"garden":{"file":"mauritius/garden.jpg","credit":"Photo: Condem at English Wikipedia, Public domain, via Wikimedia Commons","source":"https://commons.wikimedia.org/wiki/File:Giant_water_lilies.JPG"},"beach":{"file":"mauritius/beach.jpg","credit":"Photo: \"dronepicr\", CC BY 2.0, via Wikimedia Commons","source":"https://commons.wikimedia.org/wiki/File:Aerial_view_of_the_Trou_aux_Biches_Beach_in_Mauritius,_as_seen_from_the_south_(53698114274).jpg"},"temple":{"file":"mauritius/temple.jpg","credit":"Photo: carrotmadman6 from Mauritius, CC BY 2.0, via Wikimedia Commons","source":"https://commons.wikimedia.org/wiki/File:Ganga_Talao_(5489050038).jpg"},"sunset":{"file":"mauritius/sunset.jpg","credit":"Photo: Dennis Sylvester Hurd, CC0, via Wikimedia Commons","source":"https://commons.wikimedia.org/wiki/File:A_Sunday_Sunset_-_Flic-en-Flac.jpg"}},"options":[{"id":"boutique","name":"Boutique stay + driver","tag":"Cheapest","routeLine":"Delhi → Mauritius → one-stop flight home → Kolkata","badges":["🏝️ 5 nights, north coast","🚗 Driver for the sightseeing days"],"budget":{"flights":140000,"stays":65000,"food":40000,"activities":25000,"local":45000},"summary":"A well-rated boutique hotel or guesthouse near Trou aux Biches or Grand Baie, with a driver for Port Louis and Chamarel. The most flexible and cheapest way to do Mauritius, and the one with the most to see.","pros":["Cheapest of the three, about ₹3.15L all-in","Most freedom: markets, museums and views with a driver","Good value food, with vegetarian and non-vegetarian everywhere","Keeps about ₹85k spare within the ₹4L cap"],"cons":["February is hot, humid and rainy, with cyclone season","No direct flight to Kolkata","Less of a \"resort\" feel","Flight costs are estimates, not live quotes"],"travel":[{"label":"Out · Sat 20 Feb","value":"Delhi → Mauritius, about 8 hours nonstop. Round trips run about ₹58-62k per person, an estimate from search results."},{"label":"Back · Thu 25 Feb","value":"Mauritius → Delhi or Mumbai → Kolkata, one stop. There is no direct flight to Kolkata."},{"label":"Flights total","value":"About ₹1.4L for two, including the hop to Kolkata. Not a live quote."},{"label":"Local","value":"A driver is about ₹4k a day for sightseeing (an estimate), plus airport transfers."}],"lockFirst":{"flights":"Get live quotes for Delhi → Mauritius and the return via Delhi or Mumbai to Kolkata, and book them as one ticket each way.","stay":"A boutique hotel or guesthouse near Trou aux Biches or Grand Baie, breakfast included, five nights.","dinner":"Reserve a table by the sea for Wed 24 Feb."},"days":[{"day":"Day 1","date":"Sat · 20 Feb","place":"Delhi → Mauritius","emoji":"✈️","title":"Fly out, land by the sea.","note":"A direct flight from Delhi takes about eight hours. Check the schedule; arrival time decides how long the transfer feels.","moments":[{"icon":"✈️","time":"Flight","label":"Delhi → Mauritius, about 8 hours nonstop (check the schedule)"},{"icon":"🚗","time":"Arrive","label":"Transfer to your stay on the north coast (about 45 minutes to 1.5 hours, depending on the coast)"},{"icon":"🌅","time":"Evening","label":"Check in, sunset by the sea"}],"dinner":"A simple dinner where you are staying. Early night.","image":"sunset"},{"day":"Day 2","date":"Sun · 21 Feb","place":"North coast","emoji":"🏖️","title":"Do nothing by the lagoon.","note":"A slow first full day. Port Louis is quiet on Sundays, so keep this one for the beach.","moments":[{"icon":"🏖️","time":"Morning","label":"Beach and pool at Trou aux Biches or Grand Baie"},{"icon":"🎨","time":"Afternoon","label":"Sketch the lagoon colours"},{"icon":"🌅","time":"Evening","label":"Sunset walk and an easy dinner"}],"dinner":"Fresh fish or octopus curry. Vegetarian dishes are easy to find.","image":"beach"},{"day":"Day 3","date":"Mon · 22 Feb","place":"Port Louis","emoji":"🧺","title":"Markets, museums, waterfront.","note":"Port Louis is busiest on weekdays, so this is the city day. Start early before the heat and the afternoon showers.","moments":[{"icon":"🧺","time":"Morning","label":"Central Market: spices, herbal teas, street snacks"},{"icon":"🎨","time":"Midday","label":"Blue Penny Museum: art and history"},{"icon":"🏛️","time":"Afternoon","label":"Aapravasi Ghat, the UNESCO heritage site"},{"icon":"🌆","time":"Evening","label":"Dinner at the Caudan Waterfront"}],"dinner":"Waterfront dinner. Try dholl puri and gateaux piments from the market earlier for veg.","image":"market"},{"day":"Day 4","date":"Tue · 23 Feb","place":"South: Chamarel","emoji":"🌈","title":"The view day.","note":"The south-west is the scenic side: coloured earth, a waterfall, and the Le Morne mountain. Book a driver for the day.","moments":[{"icon":"🚗","time":"Morning","label":"Driver to Chamarel (about Rs 4k for the day, an estimate)"},{"icon":"🌈","time":"Midday","label":"Seven Coloured Earths and the Chamarel waterfall"},{"icon":"🥃","time":"Lunch","label":"La Rhumerie de Chamarel, the rum distillery restaurant"},{"icon":"⛰️","time":"Afternoon","label":"Le Morne viewpoint on the way back"}],"dinner":"Back at the stay for a quiet dinner.","image":"chamarel"},{"day":"Day 5","date":"Wed · 24 Feb","place":"Pamplemousses","emoji":"🌿","title":"Garden, art, and the special dinner.","note":"A gentle last full day: the famous giant water-lily garden, a creative session, then dress up once.","moments":[{"icon":"🌿","time":"Morning","label":"Pamplemousses botanical garden and the giant water-lily pond"},{"icon":"🎨","time":"Afternoon","label":"A painting or craft session (ask your stay; availability not checked)"},{"icon":"🕯️","time":"Evening","label":"Special dinner by the sea"}],"dinner":"Reserved table by the sea. Flag veg needs in advance.","image":"garden"},{"day":"Day 6","date":"Thu · 25 Feb","place":"Mauritius → Kolkata","emoji":"🏠","title":"A slow last morning.","note":"There is no direct flight to Kolkata, so the way home goes via Delhi or Mumbai. Check connection times before booking.","moments":[{"icon":"🥐","time":"Morning","label":"Slow breakfast, last souvenirs (vanilla, tea, rum)"},{"icon":"🚗","time":"Midday","label":"Transfer to the airport (timing depends on the flights)"},{"icon":"✈️","time":"Flight","label":"Mauritius → Delhi or Mumbai → Kolkata, one stop"}],"dinner":"Dinner at home.","image":"lemorne"}]},{"id":"resort-hb","name":"Beach resort, half board","tag":"Most relaxing","routeLine":"Delhi → Mauritius → one-stop flight home → Kolkata","badges":["🏝️ 5 nights beach resort","🍽️ Half board"],"budget":{"flights":140000,"stays":125000,"food":25000,"activities":25000,"local":30000},"summary":"A 4-star beach resort on the north or west coast with half board, so dinner is sorted. Port Louis and Chamarel are done as day trips with a driver, and the rest of the time is pool and lagoon.","pros":["Resort comfort with dinner included","Day trips for the markets and views, a lagoon for the rest","Keeps about ₹55k spare within the ₹4L cap"],"cons":["February is hot, humid and rainy, with cyclone season","About ₹3.45L all-in, so little room to upgrade","No direct flight to Kolkata","Prices are estimates; February is peak"],"travel":[{"label":"Out · Sat 20 Feb","value":"Delhi → Mauritius, about 8 hours nonstop. Round trips run about ₹58-62k per person, an estimate from search results."},{"label":"Back · Thu 25 Feb","value":"Mauritius → Delhi or Mumbai → Kolkata, one stop."},{"label":"Flights total","value":"About ₹1.4L for two, including the hop to Kolkata. Not a live quote."},{"label":"Resort","value":"A 4-star half-board room is about ₹20-30k a night in February (an estimate)."}],"lockFirst":{"flights":"Get live quotes first and book Delhi → Mauritius and the return as one ticket each way.","stay":"A 4-star beach resort on the north or west coast, half board, five nights. Ask for an exact 20-25 Feb quote.","dinner":"Book the resort’s best restaurant for Wed 24 Feb."},"days":[{"day":"Day 1","date":"Sat · 20 Feb","place":"Delhi → Mauritius","emoji":"✈️","title":"Fly out, land by the sea.","note":"Flight and transfer take most of the day. By evening you should be on the beach.","moments":[{"icon":"✈️","time":"Flight","label":"Delhi → Mauritius, about 8 hours nonstop (check the schedule)"},{"icon":"🚗","time":"Arrive","label":"Transfer to your resort (about 45 minutes to 1.5 hours, depending on the coast)"},{"icon":"🌅","time":"Evening","label":"Check in, sunset by the sea"}],"dinner":"A simple dinner where you are staying. Early night.","image":"sunset"},{"day":"Day 2","date":"Sun · 21 Feb","place":"North coast","emoji":"🏖️","title":"Do noth